import{_ as o,c as a,o as t,aj as r}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{"outline":"deep","prev":{"text":"Refund Policy","link":"/refund-policy"},"next":{"text":"Trading with PAV Course","link":"/trading-with-pav-course"}},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}'),i={name:"privacy-policy.md"};function n(s,e,c,l,u,h){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><strong>Last updated:</strong> 26 July 2025<br> Our website address is: <a href="/sk/">https://ystc-in.github.io/sk</a>.<br> At <strong>YS Trading Coach</strong>, we are committed to protecting your privacy as a customer and an online visitor to our website.<br> We use the information we collect about you to maximize the services that we provide to you. We respect the privacy and confidentiality of the information provided by you and adhere to it. Please read our privacy policy below carefully.</p><h3 id="information-we-collect-from-you" tabindex="-1">Information we collect from you <a class="header-anchor" href="#information-we-collect-from-you" aria-label="Permalink to &quot;Information we collect from you&quot;">​</a></h3><p>In the course of your visits to our website or use of our products and services, we may obtain the following information about you: name, company name, email address, telephone number, billing address, geographic location, IP address, survey responses, support queries, post comments and social media handles (together ‘Personal Data’).</p><p>Our services are not directed to persons under 18 and we do not knowingly collect Personal Data from anyone under 18. If we become aware that a child under 18 has provided us with Personal Data, we will delete that information as quickly as possible. If you are the parent or guardian of a child and you believe they have provided us with Personal Data without your consent, then please contact us.</p><p>You can review, correct, update or delete your Personal Data by either logging into your account and making the changes yourself or contacting us directly to do so.</p><h3 id="how-we-use-your-information" tabindex="-1">How we use your Information <a class="header-anchor" href="#how-we-use-your-information" aria-label="Permalink to &quot;How we use your Information&quot;">​</a></h3><p>Personally Identifiable Information: We use the information we collect to deliver our services to you, including: communicating with you, providing technical support, notifying you of updates and offers, sharing useful content, measuring customer satisfaction, diagnosing problems and providing you with a personalized website experience.<br> Marketing communications are only sent to you if you have requested or subscribed to them. You can opt out of our marketing communications at any time by unsubscribing or emailing us and your request will be actioned immediately.</p><p>Non-Personally Identifiable Information: We also use the information we collect in aggregated and anonymized forms to improve our services, including: administering our website, producing reports and analytics, advertising our products and services, identifying user demands and assisting in meeting customer needs generally.<br> Any information you choose to make publicly available, such as blog comments and testimonials on our website, will be available for others to see. If you subsequently remove this information, copies may remain viewable in cached and archived pages on other websites or if others have copied or saved the information.</p><h3 id="storage-and-security-of-your-information" tabindex="-1">Storage and Security of your Information <a class="header-anchor" href="#storage-and-security-of-your-information" aria-label="Permalink to &quot;Storage and Security of your Information&quot;">​</a></h3><p>We will use all reasonable means to protect the confidentiality of your Personal Data while in our possession or control. All information we receive from you is stored and protected on our secure servers from unauthorized use or access. Credit card information is encrypted before transmission and is not stored by us on our servers.</p><p>We retain your personal information for as long as needed to provide services to you and as otherwise necessary to comply with our legal obligations, resolve disputes and enforce our agreements.<br> In the event there is a breach of our security and your Personal Data is compromised, we will promptly notify you in compliance with the applicable law.</p><h3 id="cookies" tabindex="-1">Cookies <a class="header-anchor" href="#cookies" aria-label="Permalink to &quot;Cookies&quot;">​</a></h3><p>A cookie is a small file placed in your web browser that collects information about your web browsing behavior on our site. Use of cookies allows a website to tailor its configuration to your needs and preferences. Cookies do not access information stored on your computer or any Personal Data (e.g. name, address, email address or telephone number). Most web browsers automatically accept cookies but you can choose to reject cookies by changing your browser settings. This may, however, prevent you from taking full advantage of our website.</p><p>Our website uses cookies to analyze website traffic, provide social media sharing and liking functionality and help us provide a better website visitor experience.</p><h3 id="sharing-your-information-with-third-parties" tabindex="-1">Sharing your Information with Third Parties <a class="header-anchor" href="#sharing-your-information-with-third-parties" aria-label="Permalink to &quot;Sharing your Information with Third Parties&quot;">​</a></h3><p>We do not and will not sell or deal in Personal Data or any customer information.</p><p>Your Personal Data details are only disclosed to third party suppliers when it is required by law, for goods or services which you have purchased, for payment processing or to protect our copyright, trademarks and other legal rights. To the extent that we do share your Personal Data with a service provider, we would only do so if that party has agreed to comply with our privacy standards as described in this privacy policy and in accordance with applicable law. Our contracts with third parties prohibit them from using any of your Personal Data for any purpose other than that for which it was shared.</p><h3 id="disclosure-of-your-information" tabindex="-1">Disclosure of your Information <a class="header-anchor" href="#disclosure-of-your-information" aria-label="Permalink to &quot;Disclosure of your Information&quot;">​</a></h3><p>We may from time to time need to disclose certain information, which may include your Personal Data, to comply with a legal requirement, such as a law, regulation, court order, subpoena, warrant, in the course of a legal proceeding or in response to a law enforcement agency request. Also, we may use your Personal Data to protect the rights, property or safety of YS Trading Coach, our customers or third parties.</p><p>If there is a change of control in one of our businesses (whether by merger, sale, transfer of assets or otherwise) customer information, which may include your Personal Data, could be transferred to a purchaser under a confidentiality agreement. We would only disclose your Personal Data in good faith and where required by any of the above circumstances.</p><h3 id="links-to-other-websites" tabindex="-1">Links to other Websites <a class="header-anchor" href="#links-to-other-websites" aria-label="Permalink to &quot;Links to other Websites&quot;">​</a></h3><p>This website may contain links to other websites. These links are meant for your convenience only. Links to third party websites do not constitute sponsorship or endorsement or approval of these websites. Please be aware that we are not responsible for the privacy practices of such other websites. We encourage our users to be aware, when they leave our website, to read the privacy statements of each and every website that collects personally identifiable information. This privacy policy applies solely to information collected by this website.</p><hr><h3 id="our-responsibilities-under-gdpr-general-data-protection-regulation" tabindex="-1">OUR RESPONSIBILITIES UNDER (GDPR) GENERAL DATA PROTECTION REGULATION <a class="header-anchor" href="#our-responsibilities-under-gdpr-general-data-protection-regulation" aria-label="Permalink to &quot;OUR RESPONSIBILITIES UNDER (GDPR) GENERAL DATA PROTECTION REGULATION&quot;">​</a></h3><p>If you are a resident of the EU or UK you have certain rights and protections under the EU and UK GDPR regarding the processing of your Personal Data.</p><p>We collect, use and store your Personal Data to enable us to provide you with our goods or services and information about them. We rely on the following lawful means of processing your Personal Data:<br> – Where it is necessary to fulfil a contract with you. This includes where we collect your Personal Data to enable us to send you our goods or provide you with our services.<br> – Where you have given us valid consent to use your Personal Data. We will rely on that consent and only use the Personal Data for the specific purpose for which you have given consent. This includes where we email newsletters or send mobile phone notifications.<br> – We may also process your Personal Data where it is to further our legitimate interests which could include usage statistics, analytics and internal analysis so we can improve our services to you.</p><h3 id="your-rights-as-an-eu-or-uk-resident" tabindex="-1">YOUR RIGHTS AS AN EU OR UK RESIDENT <a class="header-anchor" href="#your-rights-as-an-eu-or-uk-resident" aria-label="Permalink to &quot;YOUR RIGHTS AS AN EU OR UK RESIDENT&quot;">​</a></h3><p>If you are a resident of the EU or UK you have various rights including the:<br> – Right to be informed;<br> – Right of access;<br> – Right to rectification;<br> – Right to object;<br> – Right to restriction of processing;<br> – Right to erasure or to be forgotten;<br> – Right to data portability; and<br> – Right not to be subject to automated processing.</p><p>If you want to access your Personal Data or ask for the information to be corrected, please contact us. In some circumstances, you also have a right to object to or ask that we restrict certain processing activities or delete your Personal Data. If you would like to limit or request deletion of your Personal Data or exercise any other rights you can do so by contacting us.</p><h3 id="withdrawing-your-consent" tabindex="-1">WITHDRAWING YOUR CONSENT <a class="header-anchor" href="#withdrawing-your-consent" aria-label="Permalink to &quot;WITHDRAWING YOUR CONSENT&quot;">​</a></h3><p>You can withdraw your consent to our collection or processing of your Personal Data. You can do so by contacting us or by opting out of email newsletter communications by following the instructions in those emails, by clicking unsubscribe or by using the opt out option on website. If you withdraw your consent to the use of your Personal Data, you may not have access to our services and we might not be able to provide you with our services. In some circumstances, where we have a legal basis to do so, we may continue to process your information after you have withdrawn consent. For example, if it is necessary to comply with an independent legal obligation or if it is necessary to do so to protect our legitimate interest in keeping our services secure.</p><h3 id="our-compliance" tabindex="-1">OUR COMPLIANCE <a class="header-anchor" href="#our-compliance" aria-label="Permalink to &quot;OUR COMPLIANCE&quot;">​</a></h3><p>We comply with the GDPR protection directives set out by the EU and UK regarding the collection, use and retention of Personal Data from EU member countries and the UK. All Personal Data stored on our platform is treated as confidential. It is stored securely and is only accessed by authorized personnel. Our collection is limited in relation to what is necessary, for the purpose for which the Personal Data is processed, and kept only for so long as is necessary for the purpose for which the Personal Data was collected. We implement and maintain appropriate technical, security and organizational measures to protect Personal Data against unauthorized or unlawful processing or use, and against accidental loss, destruction, damage, theft or disclosure. We ensure the encryption and pseudonymization of Personal Data and we have adequate cyber security measures in place.</p><h3 id="your-acknowledgement" tabindex="-1">YOUR ACKNOWLEDGEMENT <a class="header-anchor" href="#your-acknowledgement" aria-label="Permalink to &quot;YOUR ACKNOWLEDGEMENT&quot;">​</a></h3><p>By providing us with your Personal Data, you consent to us disclosing it to third parties who reside outside the EU or UK. We will ensure that those third parties are GDPR compliant.</p><h3 id="contact-us" tabindex="-1">Contact Us <a class="header-anchor" href="#contact-us" aria-label="Permalink to &quot;Contact Us&quot;">​</a></h3><p>If you have any questions or concerns at any time about our privacy policy or the use of your Personal Data, please <a href="/sk/contact.html">contact us</a> and we will respond within 48 hours.</p><h3 id="change-in-privacy-policy" tabindex="-1">Change in Privacy Policy <a class="header-anchor" href="#change-in-privacy-policy" aria-label="Permalink to &quot;Change in Privacy Policy&quot;">​</a></h3><p>As we plan to ensure our privacy policy remains current, this policy is subject to change. We may modify this policy at any time, in our sole discretion and all modifications will be effective immediately upon our posting of the modifications on this website. Please return periodically to review our privacy policy.</p>',40)]))}const p=o(i,[["render",n]]);export{y as __pageData,p as default};
